-- Configuracion dinamica: global y alcances, valores JSON tipados y rangos temporales.
CREATE TABLE CATALOG.PARAMETER_DEFINITION (
	CODE VARCHAR(100) PRIMARY KEY,
	DESCRIPTION TEXT NOT NULL,
	DATA_TYPE VARCHAR(20) NOT NULL CHECK (
		DATA_TYPE IN ('boolean', 'integer', 'numeric', 'text', 'jsonb')
	),
	DEFAULT_VALUE JSONB NOT NULL,
	MIN_NUMBER NUMERIC,
	MAX_NUMBER NUMERIC,
	ALLOWED_VALUES JSONB,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (
		MIN_NUMBER IS NULL
		OR MAX_NUMBER IS NULL
		OR MIN_NUMBER <= MAX_NUMBER
	)
);

CREATE TABLE CATALOG.PARAMETER_VALUE (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	CODE VARCHAR(100) NOT NULL REFERENCES CATALOG.PARAMETER_DEFINITION (CODE),
	SCOPE_TYPE VARCHAR(20) NOT NULL DEFAULT 'global' CHECK (
		SCOPE_TYPE IN (
			'global',
			'department',
			'municipality',
			'category',
			'business',
			'branch'
		)
	),
	SCOPE_ID UUID,
	VALUE JSONB NOT NULL,
	VALID_FROM TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	VALID_TO TIMESTAMPTZ,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (
		(
			SCOPE_TYPE = 'global'
			AND SCOPE_ID IS NULL
		)
		OR (
			SCOPE_TYPE <> 'global'
			AND SCOPE_ID IS NOT NULL
		)
	),
	CHECK (
		VALID_TO IS NULL
		OR VALID_TO > VALID_FROM
	)
);

ALTER TABLE CATALOG.PARAMETER_VALUE
ADD CONSTRAINT PARAMETER_NO_OVERLAP EXCLUDE USING GIST (
	CODE
	WITH
		=,
		SCOPE_TYPE
	WITH
		=,
		(
			COALESCE(
				SCOPE_ID,
				'00000000-0000-0000-0000-000000000000'::UUID
			)
		)
	WITH
		=,
		TSTZRANGE (VALID_FROM, VALID_TO, '[)')
	WITH
		&&
)
WHERE
	(ACTIVE);

CREATE INDEX PARAMETER_LOOKUP_IDX ON CATALOG.PARAMETER_VALUE (CODE, SCOPE_TYPE, SCOPE_ID, VALID_FROM DESC)
WHERE
	ACTIVE;

CREATE OR REPLACE FUNCTION CATALOG.VALIDATE_PARAMETER_DATA (
	P_CODE TEXT,
	P_TYPE TEXT,
	P_VALUE JSONB,
	P_MIN NUMERIC,
	P_MAX NUMERIC,
	P_ALLOWED JSONB
) RETURNS VOID LANGUAGE PLPGSQL IMMUTABLE AS $$
DECLARE typ text := jsonb_typeof(p_value); n numeric;
BEGIN
 IF p_value IS NULL OR
    (p_type='boolean' AND typ<>'boolean') OR
    (p_type IN ('integer','numeric') AND typ<>'number') OR
    (p_type='text' AND typ<>'string')
 THEN RAISE EXCEPTION 'Tipo invalido para parametro %',p_code; END IF;
 IF p_type IN ('integer','numeric') THEN
  n:=(p_value#>>'{}')::numeric;
  IF (p_type='integer' AND n<>trunc(n))
     OR (p_min IS NOT NULL AND n<p_min) OR (p_max IS NOT NULL AND n>p_max)
  THEN RAISE EXCEPTION 'Fuera de rango: %',p_code; END IF;
 END IF;
 IF p_allowed IS NOT NULL THEN
  IF jsonb_typeof(p_allowed)<>'array' THEN RAISE EXCEPTION 'allowed_values debe ser array: %',p_code; END IF;
  IF NOT p_allowed @> jsonb_build_array(p_value)
  THEN RAISE EXCEPTION 'Valor no permitido: %',p_code; END IF;
 END IF;
 -- Contratos de los consumidores activos; no basta con ampliar min/max en la definicion.
 IF p_code IN ('photo.max_bytes','search.default_radius_m','search.default_limit','analytics.archive_after_days') THEN
  IF p_type<>'integer' THEN RAISE EXCEPTION 'Parametro % requiere integer',p_code; END IF;
  n:=(p_value#>>'{}')::numeric;
  IF n<1 OR n>(CASE p_code WHEN 'photo.max_bytes' THEN 52428800
       WHEN 'search.default_radius_m' THEN 50000 WHEN 'search.default_limit' THEN 100 ELSE 365 END)
  THEN RAISE EXCEPTION 'Valor incompatible con consumidor: %',p_code; END IF;
 ELSIF p_code='review.moderation_post' AND p_type<>'boolean' THEN
  RAISE EXCEPTION 'Parametro % requiere boolean',p_code;
 END IF;
END $$;

CREATE OR REPLACE FUNCTION CATALOG.CHECK_PARAMETER_DEFINITION () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
DECLARE v record;
BEGIN
 PERFORM catalog.validate_parameter_data(NEW.code,NEW.data_type,NEW.default_value,
  NEW.min_number,NEW.max_number,NEW.allowed_values);
 FOR v IN SELECT value FROM catalog.parameter_value WHERE code=NEW.code AND active LOOP
  PERFORM catalog.validate_parameter_data(NEW.code,NEW.data_type,v.value,
   NEW.min_number,NEW.max_number,NEW.allowed_values);
 END LOOP;
 RETURN NEW;
END $$;

CREATE TRIGGER PARAMETER_DEFINITION_CHECK
BEFORE INSERT OR UPDATE ON CATALOG.PARAMETER_DEFINITION FOR EACH ROW
EXECUTE FUNCTION CATALOG.CHECK_PARAMETER_DEFINITION ();

CREATE OR REPLACE FUNCTION CATALOG.CHECK_PARAMETER () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
DECLARE d catalog.parameter_definition%ROWTYPE; valid_scope boolean;
BEGIN
 -- Una baja no exige que el padre o alcance todavia este vigente.
 IF NOT NEW.active THEN RETURN NEW; END IF;
 SELECT * INTO STRICT d FROM catalog.parameter_definition WHERE code=NEW.code AND active FOR SHARE;
 PERFORM catalog.validate_parameter_data(NEW.code,d.data_type,NEW.value,d.min_number,d.max_number,d.allowed_values);
 -- Solo los alcances consumidos en el MVP se administran: global y tamano de foto por sucursal.
 IF NEW.scope_type<>'global' AND NOT (NEW.code='photo.max_bytes' AND NEW.scope_type='branch') THEN
  RAISE EXCEPTION 'Alcance sin consumidor MVP para parametro %',NEW.code;
 END IF;
 CASE NEW.scope_type
  WHEN 'global' THEN valid_scope:=NEW.scope_id IS NULL;
  WHEN 'branch' THEN SELECT EXISTS(SELECT 1 FROM app.branch WHERE id=NEW.scope_id AND status IN ('active','temporarily_closed')) INTO valid_scope;
  ELSE valid_scope:=false;
 END CASE;
 IF NOT valid_scope THEN RAISE EXCEPTION 'Alcance inexistente o inactivo'; END IF;
 RETURN NEW;
END $$;

CREATE TRIGGER PARAMETER_CHECK
BEFORE INSERT OR UPDATE ON CATALOG.PARAMETER_VALUE FOR EACH ROW
EXECUTE FUNCTION CATALOG.CHECK_PARAMETER ();

CREATE OR REPLACE FUNCTION CATALOG.GET_PARAMETER (
	P_CODE TEXT,
	P_SCOPE_TYPE TEXT DEFAULT 'global',
	P_SCOPE_ID UUID DEFAULT NULL
) RETURNS JSONB LANGUAGE SQL STABLE AS $$
 SELECT coalesce((SELECT v.value FROM catalog.parameter_value v
  JOIN catalog.parameter_definition d ON d.code=v.code AND d.active
  WHERE v.code=p_code AND v.active AND v.valid_from<=now() AND (v.valid_to IS NULL OR v.valid_to>now())
   AND ((v.scope_type=p_scope_type AND v.scope_id IS NOT DISTINCT FROM p_scope_id)
     OR (v.scope_type='global' AND v.scope_id IS NULL))
  ORDER BY (v.scope_type<>'global') DESC,v.valid_from DESC LIMIT 1),
  (SELECT default_value FROM catalog.parameter_definition WHERE code=p_code AND active)) $$;

CREATE OR REPLACE FUNCTION CATALOG.PARAM_INT (P_CODE TEXT) RETURNS INTEGER LANGUAGE SQL STABLE AS $$
 SELECT (catalog.get_parameter(p_code)#>>'{}')::integer $$;

CREATE OR REPLACE FUNCTION CATALOG.PARAM_BOOL (P_CODE TEXT) RETURNS BOOLEAN LANGUAGE SQL STABLE AS $$
 SELECT (catalog.get_parameter(p_code)#>>'{}')::boolean $$;

-- Territorio boliviano. INE autoridad principal, OSM complementario.
-- Los poligonos se usan internamente para asignar/verificar ubicaciones.
-- El visitante selecciona zonas por nombre, no dibuja poligonos ni usa GIS.
CREATE TABLE GEO.TERRITORY (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	PARENT_ID UUID REFERENCES GEO.TERRITORY (ID),
	TERRITORY_TYPE VARCHAR(20) NOT NULL CHECK (
		TERRITORY_TYPE IN (
			'department',
			'province',
			'municipality',
			'zone',
			'neighborhood'
		)
	),
	CODE_INE VARCHAR(30),
	NAME VARCHAR(150) NOT NULL,
	SOURCE VARCHAR(20) NOT NULL DEFAULT 'INE' CHECK (SOURCE IN ('INE', 'OSM', 'MANUAL')),
	OSM_TYPE VARCHAR(30),
	OSM_ID BIGINT,
	SOURCE_VERSION VARCHAR(100),
	BOUNDARY GEOGRAPHY (MULTIPOLYGON, 4326),
	CENTROID GEOGRAPHY (POINT, 4326),
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (BTRIM(NAME) <> ''),
	CHECK (
		BOUNDARY IS NULL
		OR (
			ST_ISVALID (BOUNDARY::GEOMETRY)
			AND NOT ST_ISEMPTY (BOUNDARY::GEOMETRY)
		)
	),
	UNIQUE (TERRITORY_TYPE, CODE_INE),
	UNIQUE (OSM_TYPE, OSM_ID)
);

CREATE INDEX TERRITORY_PARENT_IDX ON GEO.TERRITORY (PARENT_ID);

CREATE INDEX TERRITORY_GIX ON GEO.TERRITORY USING GIST (BOUNDARY);

CREATE OR REPLACE FUNCTION GEO.VALIDATE_TERRITORY () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
DECLARE pt text;
BEGIN
 IF NEW.territory_type='department' AND NEW.parent_id IS NOT NULL THEN RAISE EXCEPTION 'Departamento sin padre'; END IF;
 IF NEW.territory_type<>'department' AND NEW.parent_id IS NULL THEN RAISE EXCEPTION 'Falta territorio padre'; END IF;
 IF EXISTS(SELECT 1 FROM geo.territory child WHERE child.parent_id=NEW.id AND NOT (
  (child.territory_type='province' AND NEW.territory_type='department') OR
  (child.territory_type='municipality' AND NEW.territory_type='province') OR
  (child.territory_type='zone' AND NEW.territory_type='municipality') OR
  (child.territory_type='neighborhood' AND NEW.territory_type IN ('municipality','zone'))))
 THEN RAISE EXCEPTION 'Cambio invalida jerarquia territorial de hijos'; END IF;
 IF NEW.parent_id IS NULL THEN RETURN NEW; END IF;
 SELECT territory_type INTO pt FROM geo.territory WHERE id=NEW.parent_id;
 IF NOT ((NEW.territory_type='province' AND pt='department') OR
         (NEW.territory_type='municipality' AND pt='province') OR
         (NEW.territory_type='zone' AND pt='municipality') OR
         (NEW.territory_type='neighborhood' AND pt IN ('municipality','zone'))) THEN
   RAISE EXCEPTION 'Jerarquia territorial invalida: % bajo %',NEW.territory_type,pt; END IF;
 IF EXISTS (WITH RECURSIVE a AS (
 SELECT id,parent_id,ARRAY[id] AS path FROM geo.territory WHERE id=NEW.parent_id
 UNION ALL SELECT t.id,t.parent_id,a.path||t.id FROM geo.territory t JOIN a ON t.id=a.parent_id WHERE NOT t.id=ANY(a.path)
 ) SELECT 1 FROM a WHERE id=NEW.id) THEN RAISE EXCEPTION 'Ciclo territorial'; END IF;
 RETURN NEW;
END $$;

CREATE TRIGGER TERRITORY_VALIDATE
BEFORE INSERT OR UPDATE OF PARENT_ID,
TERRITORY_TYPE ON GEO.TERRITORY FOR EACH ROW
EXECUTE FUNCTION GEO.VALIDATE_TERRITORY ();

CREATE OR REPLACE FUNCTION GEO.RESOLVE_TERRITORY (P_POINT GEOGRAPHY) RETURNS UUID LANGUAGE SQL STABLE AS $$
 SELECT t.id FROM geo.territory t WHERE t.active AND t.boundary IS NOT NULL
 AND ST_Covers(t.boundary,p_point) ORDER BY
 CASE territory_type WHEN 'neighborhood' THEN 1 WHEN 'zone' THEN 2 WHEN 'municipality' THEN 3
 WHEN 'province' THEN 4 ELSE 5 END, ST_Area(t.boundary) LIMIT 1 $$;

-- Negocios, sucursales y administradores (ID referencial de framework).
CREATE TABLE APP.BUSINESS (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	SLUG VARCHAR(160) UNIQUE,
	LEGAL_NAME VARCHAR(250),
	TRADE_NAME VARCHAR(200) NOT NULL,
	TAX_ID VARCHAR(50) UNIQUE,
	DESCRIPTION TEXT,
	STATUS VARCHAR(20) NOT NULL DEFAULT 'pending' REFERENCES CATALOG.BUSINESS_STATUS (CODE),
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (BTRIM(TRADE_NAME) <> ''),
	CHECK (
		SLUG IS NULL
		OR SLUG ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
	)
);

-- Propiedad N:N. El backend valida las cuentas; los UUID de usuario no tienen FK a Identity.
CREATE TABLE APP.BUSINESS_OWNER (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BUSINESS_ID UUID NOT NULL REFERENCES APP.BUSINESS (ID),
	USER_ID UUID NOT NULL,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	UNIQUE (BUSINESS_ID, USER_ID)
);

CREATE INDEX OWNER_USER_IDX ON APP.BUSINESS_OWNER (USER_ID, BUSINESS_ID)
WHERE
	ACTIVE;

-- Suscripcion del negocio al sistema.
-- El importe acordado se conserva aunque cambie el catalogo de tipos.
CREATE TABLE APP.BUSINESS_SUBSCRIPTION (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BUSINESS_ID UUID NOT NULL REFERENCES APP.BUSINESS (ID),
	SUBSCRIPTION_TYPE_ID UUID NOT NULL REFERENCES CATALOG.SUBSCRIPTION_TYPE (ID),
	STARTS_AT TIMESTAMPTZ NOT NULL,
	ENDS_AT TIMESTAMPTZ NOT NULL,
	AMOUNT_BOB NUMERIC(14, 2) NOT NULL CHECK (AMOUNT_BOB >= 0),
	STATUS VARCHAR(20) NOT NULL DEFAULT 'pending' REFERENCES CATALOG.SUBSCRIPTION_STATUS (CODE),
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (ENDS_AT > STARTS_AT)
);

CREATE INDEX SUBSCRIPTION_BUSINESS_IDX ON APP.BUSINESS_SUBSCRIPTION (BUSINESS_ID, STARTS_AT DESC)
WHERE
	STATUS <> 'cancelled';

CREATE INDEX SUBSCRIPTION_TYPE_IDX ON APP.BUSINESS_SUBSCRIPTION (SUBSCRIPTION_TYPE_ID);

-- Registro de pagos: no procesa cobros ni activa suscripciones automaticamente.
CREATE TABLE APP.SUBSCRIPTION_PAYMENT (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	SUBSCRIPTION_ID UUID NOT NULL REFERENCES APP.BUSINESS_SUBSCRIPTION (ID),
	PAYMENT_METHOD_ID UUID REFERENCES CATALOG.PAYMENT_METHOD (ID),
	AMOUNT_BOB NUMERIC(14, 2) NOT NULL CHECK (AMOUNT_BOB > 0),
	STATUS VARCHAR(20) NOT NULL DEFAULT 'pending' REFERENCES CATALOG.SUBSCRIPTION_PAYMENT_STATUS (CODE),
	PAYMENT_REFERENCE TEXT,
	PAID_AT TIMESTAMPTZ,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (
		STATUS NOT IN ('paid', 'refunded')
		OR PAID_AT IS NOT NULL
	)
);

CREATE INDEX SUBSCRIPTION_PAYMENT_SUBSCRIPTION_IDX ON APP.SUBSCRIPTION_PAYMENT (SUBSCRIPTION_ID, CREATED_AT DESC);

CREATE INDEX SUBSCRIPTION_PAYMENT_METHOD_IDX ON APP.SUBSCRIPTION_PAYMENT (PAYMENT_METHOD_ID);

CREATE TABLE APP.BRANCH (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BUSINESS_ID UUID NOT NULL REFERENCES APP.BUSINESS (ID) ON DELETE RESTRICT,
	CODE VARCHAR(50),
	SLUG VARCHAR(160) UNIQUE,
	NAME VARCHAR(200) NOT NULL,
	ADDRESS TEXT NOT NULL,
	TERRITORY_ID UUID REFERENCES GEO.TERRITORY (ID),
	LOCATION GEOGRAPHY (POINT, 4326) NOT NULL,
	STATUS VARCHAR(30) NOT NULL DEFAULT 'active' REFERENCES CATALOG.BRANCH_STATUS (CODE),
	IS_PRIMARY BOOLEAN NOT NULL DEFAULT FALSE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	UNIQUE (BUSINESS_ID, CODE),
	CHECK (
		BTRIM(NAME) <> ''
		AND BTRIM(ADDRESS) <> ''
	),
	CHECK (
		ST_ISVALID (LOCATION::GEOMETRY)
		AND NOT ST_ISEMPTY (LOCATION::GEOMETRY)
	),
	CHECK (
		ST_X (LOCATION::GEOMETRY) BETWEEN -70.0 AND -57.0
		AND ST_Y (LOCATION::GEOMETRY) BETWEEN -23.5 AND -9.0
	)
);

-- Decision de producto: se permiten varias sucursales marcadas como principales.
CREATE INDEX BRANCH_BUSINESS_IDX ON APP.BRANCH (BUSINESS_ID)
WHERE
	STATUS IN ('active', 'temporarily_closed');

CREATE INDEX BRANCH_LOCATION_GIX ON APP.BRANCH USING GIST (LOCATION)
WHERE
	STATUS IN ('active', 'temporarily_closed');

CREATE INDEX BRANCH_TERRITORY_IDX ON APP.BRANCH (TERRITORY_ID)
WHERE
	STATUS IN ('active', 'temporarily_closed');

CREATE OR REPLACE FUNCTION APP.AUTO_TERRITORY () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
BEGIN
 IF NEW.territory_id IS NULL OR (TG_OP='UPDATE' AND NEW.location IS DISTINCT FROM OLD.location
  AND NEW.territory_id IS NOT DISTINCT FROM OLD.territory_id) THEN
  NEW.territory_id := geo.resolve_territory(NEW.location); END IF;
 RETURN NEW;
END $$;

CREATE TRIGGER BRANCH_TERRITORY
BEFORE INSERT OR UPDATE OF TERRITORY_ID,
LOCATION ON APP.BRANCH FOR EACH ROW
EXECUTE FUNCTION APP.AUTO_TERRITORY ();

-- Un negocio puede conservarse sin sucursales. No se exige una sucursal principal.
-- La autenticacion y verificacion de cuentas corresponden al backend.
-- Un negocio sin asociaciones vigentes puede reclamarse mediante un flujo autorizado del backend.
CREATE OR REPLACE FUNCTION APP.IS_BUSINESS_OWNER (P_USER_ID UUID, P_BUSINESS_ID UUID) RETURNS BOOLEAN LANGUAGE SQL STABLE AS $$
 SELECT EXISTS(SELECT 1 FROM app.business_owner o JOIN app.business b ON b.id=o.business_id
  WHERE o.business_id=p_business_id AND o.user_id=p_user_id
   AND o.active AND b.status <> 'archived') $$;

-- Creacion y publicacion atomica; el backend autentica y verifica p_user_id antes de invocar.
CREATE OR REPLACE FUNCTION APP.CREATE_BUSINESS_WITH_BRANCH (
	P_USER_ID UUID,
	P_TRADE_NAME TEXT,
	P_BRANCH_NAME TEXT,
	P_ADDRESS TEXT,
	P_LON DOUBLE PRECISION,
	P_LAT DOUBLE PRECISION,
	P_DESCRIPTION TEXT DEFAULT NULL,
	P_TERRITORY_ID UUID DEFAULT NULL,
	P_CATEGORY_IDS UUID[] DEFAULT NULL
) RETURNS UUID LANGUAGE PLPGSQL AS $$
DECLARE bid uuid; sid uuid;
BEGIN
 IF p_user_id IS NULL THEN RAISE EXCEPTION 'Usuario requerido'; END IF;
 IF coalesce(cardinality(p_category_ids),0)=0 OR EXISTS (
  SELECT 1 FROM unnest(p_category_ids) x(id)
  WHERE NOT EXISTS (SELECT 1 FROM catalog.category c WHERE c.id=x.id AND c.active)
 ) THEN RAISE EXCEPTION 'Se requiere al menos una categoria vigente'; END IF;
 INSERT INTO app.business(trade_name,description,status,created_by_user_id)
 VALUES(p_trade_name,p_description,'published',p_user_id) RETURNING id INTO bid;
 INSERT INTO app.business_owner(business_id,user_id,created_by_user_id) VALUES(bid,p_user_id,p_user_id);
 INSERT INTO app.branch(business_id,name,address,location,territory_id,is_primary)
 VALUES(bid,p_branch_name,p_address,ST_SetSRID(ST_MakePoint(p_lon,p_lat),4326)::geography,p_territory_id,true) RETURNING id INTO sid;
 INSERT INTO app.branch_category(branch_id,category_id)
 SELECT sid,x.id FROM (SELECT DISTINCT unnest(p_category_ids) AS id) x;
 RETURN bid;
END $$;

CREATE OR REPLACE FUNCTION APP.SOFT_DELETE_BRANCH (P_BRANCH_ID UUID, P_ACTOR UUID) RETURNS VOID LANGUAGE PLPGSQL AS $$
BEGIN
 UPDATE app.branch SET status='permanently_closed',deleted_at=now(),deleted_by_user_id=p_actor,is_primary=false
 WHERE id=p_branch_id AND status IN ('active','temporarily_closed');
 -- Tambien se permite dar de baja la ultima sucursal.
END $$;

CREATE OR REPLACE FUNCTION APP.SOFT_DELETE_BUSINESS (P_BUSINESS_ID UUID, P_ACTOR UUID) RETURNS VOID LANGUAGE PLPGSQL AS $$
BEGIN
 UPDATE app.business SET deleted_at=now(),deleted_by_user_id=p_actor,status='archived'
 WHERE id=p_business_id AND status <> 'archived';
 UPDATE app.branch SET status='permanently_closed',deleted_at=coalesce(deleted_at,now()),deleted_by_user_id=coalesce(deleted_by_user_id,p_actor),is_primary=false
 WHERE business_id=p_business_id AND status <> 'permanently_closed';
END $$;

