-- Horario regular admite turnos multiples, cruce de medianoche y dias de 24 horas.
CREATE TABLE APP.OPENING_HOUR (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BRANCH_ID UUID NOT NULL REFERENCES APP.BRANCH (ID),
	WEEKDAY SMALLINT NOT NULL CHECK (WEEKDAY BETWEEN 0 AND 6),
	OPENS_AT TIME NOT NULL,
	CLOSES_AT TIME NOT NULL,
	IS_24_HOURS BOOLEAN NOT NULL DEFAULT FALSE,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (
		(
			IS_24_HOURS
			AND OPENS_AT = TIME '00:00'
			AND CLOSES_AT = TIME '00:00'
		)
		OR (
			NOT IS_24_HOURS
			AND OPENS_AT <> CLOSES_AT
		)
	)
);

CREATE INDEX OPENING_HOUR_IDX ON APP.OPENING_HOUR (BRANCH_ID, WEEKDAY)
WHERE
	ACTIVE;

CREATE TABLE CATALOG.HOLIDAY (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	NAME VARCHAR(150) NOT NULL,
	HOLIDAY_DATE DATE NOT NULL,
	TERRITORY_ID UUID REFERENCES GEO.TERRITORY (ID), -- NULL = festivo nacional
	RECURRING_ANNUALLY BOOLEAN NOT NULL DEFAULT FALSE,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	UNIQUE NULLS NOT DISTINCT (HOLIDAY_DATE, TERRITORY_ID, NAME)
);

CREATE INDEX HOLIDAY_DATE_IDX ON CATALOG.HOLIDAY (HOLIDAY_DATE)
WHERE
	ACTIVE;

CREATE TABLE APP.BRANCH_HOUR_OVERRIDE (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BRANCH_ID UUID NOT NULL REFERENCES APP.BRANCH (ID),
	SERVICE_DATE DATE NOT NULL,
	IS_CLOSED BOOLEAN NOT NULL DEFAULT FALSE,
	IS_24_HOURS BOOLEAN NOT NULL DEFAULT FALSE,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	OPENS_AT TIME,
	CLOSES_AT TIME,
	REASON TEXT,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	UNIQUE (BRANCH_ID, SERVICE_DATE),
	CHECK (
		(
			IS_CLOSED
			AND NOT IS_24_HOURS
			AND OPENS_AT IS NULL
			AND CLOSES_AT IS NULL
		)
		OR (
			NOT IS_CLOSED
			AND OPENS_AT IS NOT NULL
			AND CLOSES_AT IS NOT NULL
			AND (
				(
					IS_24_HOURS
					AND OPENS_AT = TIME '00:00'
					AND CLOSES_AT = TIME '00:00'
				)
				OR (
					NOT IS_24_HOURS
					AND OPENS_AT <> CLOSES_AT
				)
			)
		)
	)
);

CREATE OR REPLACE FUNCTION APP.IS_HOLIDAY (P_BRANCH UUID, P_DAY DATE) RETURNS BOOLEAN LANGUAGE SQL STABLE AS $$
 WITH RECURSIVE ancestors AS (
  SELECT t.id,t.parent_id FROM geo.territory t
  JOIN app.branch b ON b.territory_id=t.id WHERE b.id=p_branch
  UNION ALL
  SELECT t.id,t.parent_id FROM geo.territory t JOIN ancestors a ON t.id=a.parent_id
 )
 SELECT EXISTS (
  SELECT 1 FROM CATALOG.holiday h WHERE h.active
  AND (h.territory_id IS NULL OR h.territory_id IN (SELECT id FROM ancestors))
  AND (h.holiday_date=p_day OR (h.recurring_annually
    AND extract(month FROM h.holiday_date)=extract(month FROM p_day)
    AND extract(day FROM h.holiday_date)=extract(day FROM p_day)))
 ) $$;

CREATE OR REPLACE FUNCTION APP.IS_OPEN_AT (P_BRANCH UUID, P_WHEN TIMESTAMPTZ DEFAULT NOW()) RETURNS BOOLEAN LANGUAGE PLPGSQL STABLE AS $$
DECLARE localts timestamp := p_when AT TIME ZONE 'America/La_Paz';
 d date := localts::date; t time := localts::time; wd int;
 ix integer; od date; oh app.branch_hour_override%ROWTYPE; has_ov boolean;
BEGIN
 IF p_when IS NULL THEN RAISE EXCEPTION 'Fecha requerida'; END IF;
 IF NOT EXISTS(SELECT 1 FROM app.branch b JOIN app.business x ON x.id=b.business_id
  WHERE b.id=p_branch
  AND b.status='active' AND x.status='published')
 THEN RETURN false; END IF;

 -- La excepcion de HOY sustituye el horario completo del dia, incluido el arrastre de ayer.
 SELECT * INTO oh FROM app.branch_hour_override
 WHERE branch_id=p_branch AND service_date=d AND active;
 IF FOUND THEN
  IF oh.is_closed THEN RETURN false; END IF;
  IF oh.is_24_hours THEN RETURN true; END IF;
  RETURN t>=oh.opens_at AND (oh.closes_at<oh.opens_at OR t<oh.closes_at);
 END IF;
 -- Un feriado cierra el dia civil completo, salvo excepcion explicita de apertura de hoy.
 IF app.is_holiday(p_branch,d) THEN RETURN false; END IF;

 FOR ix IN 0..1 LOOP
  od:=d-ix; wd:=extract(dow FROM od)::int;
  SELECT * INTO oh FROM app.branch_hour_override
  WHERE branch_id=p_branch AND service_date=od AND active;
  has_ov:=FOUND;
  IF has_ov THEN
   -- Solo un turno nocturno de ayer se arrastra; 24 horas termina a medianoche.
   IF NOT oh.is_closed AND NOT oh.is_24_hours AND ix=1
      AND oh.closes_at<oh.opens_at AND t<oh.closes_at THEN RETURN true; END IF;
  ELSIF NOT app.is_holiday(p_branch,od) AND EXISTS (
   SELECT 1 FROM app.opening_hour h
   WHERE h.branch_id=p_branch AND h.active AND h.weekday=wd
   AND ((ix=0 AND (h.is_24_hours OR
        (t>=h.opens_at AND (h.closes_at<h.opens_at OR t<h.closes_at))))
     OR (ix=1 AND NOT h.is_24_hours AND h.closes_at<h.opens_at AND t<h.closes_at))
  ) THEN RETURN true;
  END IF;
 END LOOP;
 RETURN false;
END $$;

-- Precio en BOB por sucursal y servicio/producto.
-- Precio fijo: minimo = maximo; rango: minimo < maximo. Sin fila activa: sin precio informado.
CREATE TABLE APP.SERVICE_PRODUCT_PRICE (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BRANCH_ID UUID NOT NULL,
	SERVICE_PRODUCT_ID UUID NOT NULL,
	AMOUNT_MIN_BOB NUMERIC(14, 2) NOT NULL CHECK (AMOUNT_MIN_BOB >= 0),
	AMOUNT_MAX_BOB NUMERIC(14, 2) NOT NULL CHECK (AMOUNT_MAX_BOB >= AMOUNT_MIN_BOB),
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	FOREIGN KEY (BRANCH_ID, SERVICE_PRODUCT_ID) REFERENCES APP.BRANCH_SERVICE_PRODUCT (BRANCH_ID, SERVICE_PRODUCT_ID)
);

CREATE UNIQUE INDEX SERVICE_PRODUCT_PRICE_ONE_IDX ON APP.SERVICE_PRODUCT_PRICE (BRANCH_ID, SERVICE_PRODUCT_ID)
WHERE
	ACTIVE;

-- Fotos unicamente de propietario o administrador (validacion de actor en funcion).
-- JPEG, PNG y WebP. Los bytes quedan en PostgreSQL (TOAST), no URLs ni rutas externas.
CREATE TABLE APP.BRANCH_PHOTO (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BRANCH_ID UUID NOT NULL REFERENCES APP.BRANCH (ID),
	PHOTO_DATA BYTEA NOT NULL,
	PHOTO_SHA256 BYTEA GENERATED ALWAYS AS (PG_CATALOG.SHA256 (PHOTO_DATA)) STORED,
	MIME_TYPE VARCHAR(30) NOT NULL CHECK (
		MIME_TYPE IN ('image/jpeg', 'image/png', 'image/webp')
	),
	FILE_SIZE BIGINT GENERATED ALWAYS AS (OCTET_LENGTH(PHOTO_DATA)) STORED,
	FILENAME VARCHAR(255),
	ALT_TEXT VARCHAR(300),
	IS_PRIMARY BOOLEAN NOT NULL DEFAULT FALSE,
	SORT_ORDER INTEGER NOT NULL DEFAULT 0,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID NOT NULL DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (OCTET_LENGTH(PHOTO_DATA) > 0)
);

-- Decision de producto: se permiten varias fotos principales por sucursal.
CREATE INDEX PHOTO_BRANCH_IDX ON APP.BRANCH_PHOTO (BRANCH_ID, SORT_ORDER)
WHERE
	ACTIVE;

-- Fotos del negocio, tambien sin sucursales: hash hexadecimal en audit_log;
-- bytes anteriores deduplicados en photo_blob al reemplazar, borrar o truncar.
CREATE TABLE APP.BUSINESS_PHOTO (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BUSINESS_ID UUID NOT NULL REFERENCES APP.BUSINESS (ID),
	PHOTO_DATA BYTEA NOT NULL,
	PHOTO_SHA256 BYTEA GENERATED ALWAYS AS (PG_CATALOG.SHA256 (PHOTO_DATA)) STORED,
	MIME_TYPE VARCHAR(30) NOT NULL CHECK (
		MIME_TYPE IN ('image/jpeg', 'image/png', 'image/webp')
	),
	FILE_SIZE BIGINT GENERATED ALWAYS AS (OCTET_LENGTH(PHOTO_DATA)) STORED,
	FILENAME VARCHAR(255),
	ALT_TEXT VARCHAR(300),
	IS_PRIMARY BOOLEAN NOT NULL DEFAULT FALSE,
	SORT_ORDER INTEGER NOT NULL DEFAULT 0,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID NOT NULL DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK (OCTET_LENGTH(PHOTO_DATA) > 0)
);

CREATE INDEX PHOTO_BUSINESS_IDX ON APP.BUSINESS_PHOTO (BUSINESS_ID, SORT_ORDER)
WHERE
	ACTIVE;

-- Dos hashes STORED e indices para recuperar tambien fotos vivas; costo de hash en cada escritura de bytes.
CREATE INDEX BRANCH_PHOTO_SHA256_IDX ON APP.BRANCH_PHOTO USING BTREE (PHOTO_SHA256);

CREATE INDEX BUSINESS_PHOTO_SHA256_IDX ON APP.BUSINESS_PHOTO USING BTREE (PHOTO_SHA256);

CREATE OR REPLACE FUNCTION APP.VALIDATE_PHOTO_BYTES () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
DECLARE mx integer; sig text;
BEGIN
 IF TG_TABLE_NAME='branch_photo' THEN
  mx:=(catalog.get_parameter('photo.max_bytes','branch',NEW.branch_id)#>>'{}')::integer;
 ELSE
  mx:=catalog.param_int('photo.max_bytes');
 END IF;
 IF mx IS NOT NULL AND octet_length(NEW.photo_data)>mx THEN RAISE EXCEPTION 'Imagen excede % bytes',mx; END IF;
 sig := encode(substring(NEW.photo_data FROM 1 FOR 12),'hex');
 IF NOT ((NEW.mime_type='image/jpeg' AND left(sig,6)='ffd8ff') OR
  (NEW.mime_type='image/png' AND left(sig,16)='89504e470d0a1a0a') OR
  (NEW.mime_type='image/webp' AND left(sig,8)='52494646' AND substring(sig FROM 17 FOR 8)='57454250')) THEN
  RAISE EXCEPTION 'Firma de imagen no coincide con tipo MIME'; END IF;
 RETURN NEW;
END $$;

CREATE TRIGGER PHOTO_BYTES
BEFORE INSERT OR UPDATE OF PHOTO_DATA,
BRANCH_ID,
MIME_TYPE ON APP.BRANCH_PHOTO FOR EACH ROW
EXECUTE FUNCTION APP.VALIDATE_PHOTO_BYTES ();

CREATE TRIGGER BUSINESS_PHOTO_BYTES
BEFORE INSERT OR UPDATE OF PHOTO_DATA,
MIME_TYPE ON APP.BUSINESS_PHOTO FOR EACH ROW
EXECUTE FUNCTION APP.VALIDATE_PHOTO_BYTES ();

-- El backend autentica el actor y deriva p_is_admin de sus privilegios.
CREATE OR REPLACE FUNCTION APP.ADD_BUSINESS_PHOTO (
	P_BUSINESS UUID,
	P_USER_ID UUID,
	P_DATA BYTEA,
	P_MIME TEXT,
	P_PRIMARY BOOLEAN DEFAULT FALSE,
	P_FILENAME TEXT DEFAULT NULL,
	P_ALT TEXT DEFAULT NULL,
	P_IS_ADMIN BOOLEAN DEFAULT FALSE
) RETURNS UUID LANGUAGE PLPGSQL AS $$
DECLARE pid uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM app.business WHERE id=p_business AND status <> 'archived') THEN
  RAISE EXCEPTION 'Negocio inexistente o inactivo'; END IF;
 IF NOT coalesce(p_is_admin,false) AND NOT app.is_business_owner(p_user_id,p_business) THEN
  RAISE EXCEPTION 'Solo propietario o administrador'; END IF;
 INSERT INTO app.business_photo(business_id,created_by_user_id,photo_data,mime_type,is_primary,filename,alt_text)
 VALUES(p_business,p_user_id,p_data,p_mime,p_primary,p_filename,p_alt) RETURNING id INTO pid;
 RETURN pid;
END $$;

-- Con una sola cuenta de BD, el backend DEBE autenticar el actor antes de llamar esta funcion.
CREATE OR REPLACE FUNCTION APP.ADD_PHOTO (
	P_BRANCH UUID,
	P_USER_ID UUID,
	P_DATA BYTEA,
	P_MIME TEXT,
	P_PRIMARY BOOLEAN DEFAULT FALSE,
	P_FILENAME TEXT DEFAULT NULL,
	P_ALT TEXT DEFAULT NULL,
	P_IS_ADMIN BOOLEAN DEFAULT FALSE
) RETURNS UUID LANGUAGE PLPGSQL AS $$
DECLARE bid uuid; pid uuid;
BEGIN
 SELECT business_id INTO STRICT bid FROM app.branch WHERE id=p_branch AND status IN ('active','temporarily_closed');
 IF NOT coalesce(p_is_admin,false) AND NOT app.is_business_owner(p_user_id,bid) THEN
  RAISE EXCEPTION 'Solo propietario o administrador'; END IF;
 INSERT INTO app.branch_photo(branch_id,created_by_user_id,photo_data,mime_type,is_primary,filename,alt_text)
 VALUES(p_branch,p_user_id,p_data,p_mime,p_primary,p_filename,p_alt) RETURNING id INTO pid;
 RETURN pid;
END $$;

-- Reseñas: varias por usuario y sucursal, moderacion posterior, una respuesta de propietario por reseña.
CREATE TABLE APP.REVIEW (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BRANCH_ID UUID NOT NULL REFERENCES APP.BRANCH (ID),
	USER_ID UUID NOT NULL,
	RATING SMALLINT NOT NULL CHECK (RATING BETWEEN 1 AND 5),
	TITLE VARCHAR(200),
	BODY TEXT,
	MODERATION_STATUS VARCHAR(20) NOT NULL DEFAULT (
		CASE
			WHEN CATALOG.PARAM_BOOL ('review.moderation_post') THEN 'visible'
			ELSE 'hidden'
		END
	) REFERENCES CATALOG.REVIEW_MODERATION_STATUS (CODE),
	MODERATION_REASON TEXT,
	REPLY_TEXT TEXT,
	REPLY_BY_USER_ID UUID,
	REPLIED_AT TIMESTAMPTZ,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	MODERATED_AT TIMESTAMPTZ,
	MODERATED_BY_USER_ID UUID,
	CHECK (
		(
			REPLY_TEXT IS NULL
			AND REPLY_BY_USER_ID IS NULL
			AND REPLIED_AT IS NULL
		)
		OR (
			REPLY_TEXT IS NOT NULL
			AND BTRIM(REPLY_TEXT) <> ''
			AND REPLY_BY_USER_ID IS NOT NULL
			AND REPLIED_AT IS NOT NULL
		)
	)
);

CREATE INDEX REVIEW_BRANCH_IDX ON APP.REVIEW (BRANCH_ID, MODERATION_STATUS, CREATED_AT DESC)
WHERE
	MODERATION_STATUS <> 'deleted';

CREATE INDEX REVIEW_USER_IDX ON APP.REVIEW (USER_ID, CREATED_AT DESC)
WHERE
	MODERATION_STATUS <> 'deleted';

-- La respuesta se guarda en la misma fila de la resena; devuelve el ID de la resena.
CREATE OR REPLACE FUNCTION APP.REPLY_TO_REVIEW (P_REVIEW_ID UUID, P_USER_ID UUID, P_TEXT TEXT) RETURNS UUID LANGUAGE PLPGSQL AS $$
DECLARE bid uuid;
BEGIN
 SELECT b.business_id INTO STRICT bid FROM app.review r JOIN app.branch b ON b.id=r.branch_id
 WHERE r.id=p_review_id AND r.moderation_status <> 'deleted' AND b.status IN ('active','temporarily_closed');
 IF NOT app.is_business_owner(p_user_id,bid) THEN RAISE EXCEPTION 'No es propietario'; END IF;
 IF p_text IS NULL OR btrim(p_text)='' THEN RAISE EXCEPTION 'Respuesta requerida'; END IF;
 UPDATE app.review SET reply_text=p_text,reply_by_user_id=p_user_id,replied_at=clock_timestamp()
 WHERE id=p_review_id AND moderation_status <> 'deleted';
 IF NOT FOUND THEN RAISE EXCEPTION 'Resena no encontrada'; END IF;
 RETURN p_review_id;
END $$;

CREATE TABLE APP.FAVORITE (
	USER_ID UUID NOT NULL,
	BRANCH_ID UUID NOT NULL REFERENCES APP.BRANCH (ID),
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	PRIMARY KEY (USER_ID, BRANCH_ID)
);

-- El dashboard cuenta por sucursal; la PK empieza por usuario.
CREATE INDEX FAVORITE_BRANCH_IDX ON APP.FAVORITE (BRANCH_ID);

CREATE OR REPLACE FUNCTION APP.TOGGLE_FAVORITE (P_USER_ID UUID, P_BRANCH UUID) RETURNS BOOLEAN LANGUAGE PLPGSQL AS $$
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'Usuario requerido'; END IF;
  -- Serializar toggles del mismo par sin depender de una fila que podria no existir.
  PERFORM pg_advisory_xact_lock(hashtextextended('app.favorite:'||p_user_id::text||':'||p_branch::text,0));
  -- 1) Intentar desmarcar: si borra una fila, quedó desmarcado.
  DELETE FROM app.favorite
  WHERE user_id = p_user_id AND branch_id = p_branch;

  IF FOUND THEN
    RETURN false;
  END IF;

  -- 2) No existía: validar sucursal y marcar.
  IF NOT EXISTS (
    SELECT 1 FROM app.branch
    WHERE id = p_branch
      AND status IN ('active', 'temporarily_closed')
  ) THEN
    RAISE EXCEPTION 'Sucursal no disponible';
  END IF;

  INSERT INTO app.favorite (user_id, branch_id)
  VALUES (p_user_id, p_branch);

  RETURN true;
END $$;

-- Publicidad: periodo de promocion de un negocio o una sucursal.
CREATE TABLE APP.AD_PLACEMENT (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	BUSINESS_ID UUID REFERENCES APP.BUSINESS (ID),
	BRANCH_ID UUID REFERENCES APP.BRANCH (ID),
	STARTS_AT TIMESTAMPTZ NOT NULL,
	ENDS_AT TIMESTAMPTZ NOT NULL,
	PRIORITY INT NOT NULL DEFAULT 0,
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	CHECK ((BUSINESS_ID IS NULL) <> (BRANCH_ID IS NULL)),
	CHECK (ENDS_AT > STARTS_AT)
);

CREATE INDEX AD_PERIOD_IDX ON APP.AD_PLACEMENT (STARTS_AT, ENDS_AT)
WHERE
	ACTIVE;

CREATE INDEX AD_BUSINESS_IDX ON APP.AD_PLACEMENT (BUSINESS_ID)
WHERE
	BUSINESS_ID IS NOT NULL;

CREATE INDEX AD_BRANCH_IDX ON APP.AD_PLACEMENT (BRANCH_ID)
WHERE
	BRANCH_ID IS NOT NULL;

CREATE OR REPLACE FUNCTION APP.ACTIVE_ADS (P_AT TIMESTAMPTZ DEFAULT NOW()) RETURNS TABLE (AD_ID UUID, BRANCH_ID UUID, PRIORITY INT) LANGUAGE SQL STABLE AS $$
 SELECT a.id,b.id,a.priority FROM app.ad_placement a JOIN app.branch b
 ON (a.branch_id=b.id OR (a.business_id=b.business_id AND a.branch_id IS NULL))
 JOIN app.business x ON x.id=b.business_id
 WHERE a.active
 AND a.starts_at<=p_at AND a.ends_at>p_at
 AND x.status='published'
 AND b.status IN ('active','temporarily_closed') $$;

CREATE OR REPLACE FUNCTION APP.EXPIRE_ADS (P_AT TIMESTAMPTZ DEFAULT NOW()) RETURNS INTEGER LANGUAGE PLPGSQL AS $$
DECLARE n int;
BEGIN
 UPDATE app.ad_placement SET active=false WHERE active AND ends_at<=p_at;
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n;
END $$;

CREATE OR REPLACE FUNCTION APP.UNACCENT_FIXED (P_TEXT TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE PARALLEL SAFE STRICT AS $$
-- Diccionario fijo: si cambian sus reglas, reconstruir TODOS los indices sobre app.normalize.
 SELECT public.unaccent('public.unaccent'::regdictionary,p_text) $$;

CREATE OR REPLACE FUNCTION APP.NORMALIZE (P_TEXT TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $$ SELECT lower(app.unaccent_fixed(coalesce(p_text,''))) $$;

-- Sinonimos espanoles y autocompletado.
CREATE TABLE CATALOG.SEARCH_SYNONYM (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	TERM VARCHAR(150) NOT NULL,
	SYNONYM VARCHAR(150) NOT NULL,
	LOCALE VARCHAR(10) NOT NULL DEFAULT 'es-BO',
	ACTIVE BOOLEAN NOT NULL DEFAULT TRUE,
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	UPDATED_BY_USER_ID UUID,
	DELETED_BY_USER_ID UUID,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	UPDATED_AT TIMESTAMPTZ,
	DELETED_AT TIMESTAMPTZ,
	UNIQUE (TERM, SYNONYM, LOCALE)
);

CREATE INDEX BUSINESS_NAME_TRGM_IDX ON APP.BUSINESS USING GIN ((APP.NORMALIZE (TRADE_NAME)) GIN_TRGM_OPS)
WHERE
	STATUS = 'published';

CREATE INDEX BRANCH_NAME_TRGM_IDX ON APP.BRANCH USING GIN ((APP.NORMALIZE (NAME)) GIN_TRGM_OPS)
WHERE
	STATUS IN ('active', 'temporarily_closed');

-- Las expresiones coinciden con las usadas por busqueda y autocompletado.
CREATE INDEX SYNONYM_TERM_IDX ON CATALOG.SEARCH_SYNONYM (APP.NORMALIZE (TERM))
WHERE
	ACTIVE;

CREATE INDEX SYNONYM_AUTOCOMPLETE_IDX ON CATALOG.SEARCH_SYNONYM USING GIN (APP.NORMALIZE (SYNONYM) GIN_TRGM_OPS)
WHERE
	ACTIVE;

CREATE INDEX CATEGORY_NAME_TRGM_IDX ON CATALOG.CATEGORY USING GIN (APP.NORMALIZE (NAME) GIN_TRGM_OPS)
WHERE
	ACTIVE;

CREATE OR REPLACE VIEW APP.PUBLISHED_BRANCH AS
SELECT
	S.ID AS BRANCH_ID,
	B.ID AS BUSINESS_ID,
	B.TRADE_NAME,
	B.DESCRIPTION,
	S.NAME AS BRANCH_NAME,
	S.ADDRESS,
	S.TERRITORY_ID,
	S.LOCATION,
	S.STATUS AS BRANCH_STATUS,
	B.STATUS AS BUSINESS_STATUS
FROM
	APP.BRANCH S
	JOIN APP.BUSINESS B ON B.ID = S.BUSINESS_ID
WHERE
	S.STATUS IN ('active', 'temporarily_closed')
	AND B.STATUS = 'published';

-- Parametros: filtro geometrico por viewport, punto/radio, categoria y descendientes,
-- Solo publicados; SQL estatico. Patrocinio primero, luego relevancia, distancia e ID.
-- El backend convierte location a las coordenadas del mapa; el usuario no gestiona SRID.
CREATE OR REPLACE FUNCTION APP.FIND_BRANCHES (
	P_TEXT TEXT DEFAULT NULL,
	P_CENTER GEOGRAPHY DEFAULT NULL,
	P_RADIUS_M INT DEFAULT NULL,
	P_BBOX GEOGRAPHY DEFAULT NULL,
	P_CATEGORY_ID UUID DEFAULT NULL,
	P_TERRITORY_ID UUID DEFAULT NULL,
	P_OPEN_NOW BOOLEAN DEFAULT FALSE,
	P_MIN_PRICE NUMERIC DEFAULT NULL,
	P_MAX_PRICE NUMERIC DEFAULT NULL,
	P_LIMIT INT DEFAULT CATALOG.PARAM_INT ('search.default_limit'),
	P_OFFSET INT DEFAULT 0
) RETURNS TABLE (
	BRANCH_ID UUID,
	BUSINESS_ID UUID,
	TRADE_NAME VARCHAR(200),
	BRANCH_NAME VARCHAR(200),
	DISTANCE_M FLOAT8,
	RATING NUMERIC,
	REVIEW_COUNT BIGINT,
	IS_SPONSORED BOOLEAN,
	MIN_PRICE_BOB NUMERIC,
	MAX_PRICE_BOB NUMERIC,
	LOCATION GEOGRAPHY,
	BRANCH_STATUS VARCHAR(30),
	BUSINESS_STATUS VARCHAR(30),
	TOTAL_COUNT BIGINT
) LANGUAGE PLPGSQL STABLE AS $$
DECLARE q text := nullif(app.normalize(btrim(coalesce(p_text,''))),'');
 radius_m integer;
BEGIN
 IF p_limit IS NULL OR p_offset IS NULL OR p_limit NOT BETWEEN 1 AND 100 OR p_offset NOT BETWEEN 0 AND 2000 THEN
  RAISE EXCEPTION 'Paginacion invalida'; END IF;
 IF length(coalesce(p_text,''))>200 THEN RAISE EXCEPTION 'Texto demasiado largo'; END IF;
 IF p_radius_m IS NOT NULL AND (p_center IS NULL OR p_radius_m NOT BETWEEN 1 AND 50000) THEN
  RAISE EXCEPTION 'Radio invalido'; END IF;
 IF p_open_now IS NULL THEN RAISE EXCEPTION 'Filtro de apertura requerido'; END IF;
 IF (p_min_price IS NOT NULL AND p_min_price<0) OR (p_max_price IS NOT NULL AND p_max_price<0)
    OR (p_min_price IS NOT NULL AND p_max_price IS NOT NULL AND p_min_price>p_max_price) THEN
  RAISE EXCEPTION 'Rango de precio invalido'; END IF;
 IF p_center IS NOT NULL AND (ST_SRID(p_center::geometry)<>4326 OR ST_GeometryType(p_center::geometry)<>'ST_Point'
  OR ST_IsEmpty(p_center::geometry) OR ST_NDims(p_center::geometry)<>2) THEN
  RAISE EXCEPTION 'Centro debe ser Point SRID 4326'; END IF;
 IF p_bbox IS NOT NULL AND (ST_SRID(p_bbox::geometry)<>4326
  OR ST_GeometryType(p_bbox::geometry)<>'ST_Polygon'
  OR ST_IsEmpty(p_bbox::geometry) OR NOT ST_IsValid(p_bbox::geometry)
  OR ST_NDims(p_bbox::geometry)<>2
  OR NOT ST_Equals(p_bbox::geometry,ST_Envelope(p_bbox::geometry)))
 THEN RAISE EXCEPTION 'BBox debe ser un rectangulo Polygon valido y no vacio, SRID 4326'; END IF;
 radius_m:=CASE WHEN p_center IS NULL THEN NULL
  ELSE coalesce(p_radius_m,catalog.param_int('search.default_radius_m')) END;
 IF p_center IS NOT NULL AND (radius_m IS NULL OR radius_m NOT BETWEEN 1 AND 50000)
 THEN RAISE EXCEPTION 'Radio predeterminado invalido'; END IF;

 RETURN QUERY
 WITH RECURSIVE cats(id) AS (
  SELECT p_category_id WHERE p_category_id IS NOT NULL
  UNION ALL SELECT ci.id FROM catalog.category ci JOIN cats c ON ci.parent_id=c.id WHERE ci.active
 ), territories(id) AS (
  SELECT t.id FROM geo.territory t WHERE t.id=p_territory_id AND t.active
  UNION ALL
  SELECT child.id FROM geo.territory child JOIN territories parent ON child.parent_id=parent.id
  WHERE child.active
 ), synonyms AS (
  SELECT q AS term WHERE q IS NOT NULL
  UNION ALL SELECT app.normalize(ss.synonym) FROM catalog.search_synonym ss
  WHERE ss.active AND ss.locale LIKE 'es%' AND app.normalize(ss.term)=q
 ), candidates AS (
  SELECT pb.branch_id,pb.business_id,pb.trade_name,pb.branch_name,pb.location,
   pb.branch_status,pb.business_status,
   CASE WHEN p_center IS NULL THEN NULL ELSE ST_Distance(pb.location,p_center) END AS dist
  FROM app.published_branch pb
  WHERE (p_bbox IS NULL OR ST_Intersects(pb.location,p_bbox))
  AND (radius_m IS NULL OR ST_DWithin(pb.location,p_center,radius_m))
  AND (p_territory_id IS NULL OR EXISTS (
    SELECT 1 FROM app.branch br JOIN territories t ON t.id=br.territory_id WHERE br.id=pb.branch_id))
  AND (p_category_id IS NULL OR EXISTS (
    SELECT 1 FROM app.branch_category bc JOIN cats c ON c.id=bc.category_id
    WHERE bc.branch_id=pb.branch_id AND bc.active))
  AND (q IS NULL OR EXISTS (SELECT 1 FROM synonyms sy WHERE
    app.normalize(pb.trade_name) % sy.term OR app.normalize(pb.branch_name) % sy.term
    OR app.normalize(pb.trade_name) LIKE '%'||sy.term||'%'
    OR app.normalize(pb.branch_name) LIKE '%'||sy.term||'%'))
  AND (p_min_price IS NULL AND p_max_price IS NULL OR EXISTS (
    SELECT 1 FROM app.service_product_price pp
    WHERE pp.branch_id=pb.branch_id AND pp.active
     AND (p_min_price IS NULL OR pp.amount_max_bob>=p_min_price)
     AND (p_max_price IS NULL OR pp.amount_min_bob<=p_max_price)))
  AND (NOT p_open_now OR app.is_open_at(pb.branch_id,now()))
 ), ranked AS (
  SELECT c.branch_id,c.business_id,c.trade_name,c.branch_name,c.dist,c.location,
   c.branch_status,c.business_status,
   CASE WHEN r.n=0 THEN NULL ELSE r.avg_rating END AS rt,
   r.n AS rn,
   EXISTS (SELECT 1 FROM app.active_ads(now()) ads WHERE ads.branch_id=c.branch_id) AS sp,
   pr.pmin,pr.pmax
  FROM candidates c
  LEFT JOIN LATERAL (
   SELECT round(avg(rv.rating)::numeric,2) AS avg_rating,count(*) AS n FROM app.review rv
   WHERE rv.branch_id=c.branch_id AND rv.moderation_status='visible') r ON true
  LEFT JOIN LATERAL (
   SELECT min(pp.amount_min_bob) AS pmin,max(pp.amount_max_bob) AS pmax
   FROM app.service_product_price pp WHERE pp.branch_id=c.branch_id AND pp.active) pr ON true
  ORDER BY sp DESC,
   CASE WHEN q IS NOT NULL THEN similarity(app.normalize(c.trade_name),q) ELSE 0 END DESC,
   c.dist ASC NULLS LAST,c.branch_id
  LIMIT p_limit OFFSET p_offset
 )
 SELECT rk.branch_id,rk.business_id,rk.trade_name,rk.branch_name,rk.dist,rk.rt,rk.rn,rk.sp,
  rk.pmin,rk.pmax,rk.location,rk.branch_status,rk.business_status,
  tot.total
 FROM (SELECT count(*) AS total FROM candidates) tot
 LEFT JOIN ranked rk ON true;
END $$;

CREATE OR REPLACE FUNCTION APP.AUTOCOMPLETE (P_PREFIX TEXT, P_LIMIT INTEGER DEFAULT 12) RETURNS TABLE (SUGGESTION TEXT, SUGGESTION_TYPE TEXT) LANGUAGE SQL STABLE AS $$
 SELECT name,typ FROM (
 SELECT DISTINCT b.trade_name AS name,'business'::text AS typ,0 AS ord FROM app.business b
 WHERE b.status='published'
 AND app.normalize(b.trade_name) LIKE app.normalize(p_prefix)||'%'
 UNION ALL
 SELECT DISTINCT c.name,'category',1 FROM catalog.category c WHERE c.active
 AND app.normalize(c.name) LIKE app.normalize(p_prefix)||'%'
 UNION ALL
 SELECT DISTINCT s.synonym,'synonym',2 FROM CATALOG.search_synonym s WHERE s.active
 AND app.normalize(s.synonym) LIKE app.normalize(p_prefix)||'%'
 ) x ORDER BY ord,name LIMIT greatest(1,least(p_limit,30)) $$;

-- Analitica: IP y user-agent conservados en PostgreSQL; el Worker Service de .NET
-- invoca archive_events, consolidate_daily y consolidate_monthly con su propia planificacion.
-- Separacion fisica activa / historica; operaciones atomicas de archivado semanal.
CREATE TABLE APP.EVENT (
	ID UUID PRIMARY KEY DEFAULT UUIDV7(),
	EVENT_TYPE VARCHAR(50) NOT NULL,
	OCCURRED_AT TIMESTAMPTZ NOT NULL DEFAULT CLOCK_TIMESTAMP(),
	USER_ID UUID,
	SESSION_KEY VARCHAR(128),
	IP_ADDRESS INET NOT NULL,
	USER_AGENT VARCHAR(1000) NOT NULL,
	BUSINESS_ID UUID,
	BRANCH_ID UUID,
	CATEGORY_ID UUID,
	TERRITORY_ID UUID,
	QUERY_TEXT TEXT,
	SOURCE_REF TEXT,
	METADATA JSONB NOT NULL DEFAULT '{}'::JSONB
);

CREATE INDEX EVENT_TIME_BRIN ON APP.EVENT USING BRIN (OCCURRED_AT);

CREATE INDEX EVENT_TYPE_TIME ON APP.EVENT (EVENT_TYPE, OCCURRED_AT);

CREATE INDEX EVENT_BRANCH_TIME ON APP.EVENT (BRANCH_ID, OCCURRED_AT)
WHERE
	BRANCH_ID IS NOT NULL;

-- Coincide con los predicados del dashboard por anuncio y tipo.
CREATE INDEX EVENT_AD_TYPE_IDX ON APP.EVENT ((METADATA ->> 'ad_id'), EVENT_TYPE)
WHERE
	EVENT_TYPE IN ('ad_impression', 'ad_click');

CREATE TABLE APP.EVENT_HIST (LIKE APP.EVENT INCLUDING ALL);

-- Cambiar nombres de indices copiados: PostgreSQL asigna nombres distintos automaticamente.
CREATE OR REPLACE FUNCTION APP.ARCHIVE_EVENTS (P_CUTOFF TIMESTAMPTZ DEFAULT NULL) RETURNS BIGINT LANGUAGE PLPGSQL AS $$
DECLARE n bigint; cutoff timestamptz := coalesce(p_cutoff,now()-make_interval(days=>catalog.param_int('analytics.archive_after_days')));
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('cofre.archive_events'));
 WITH moved AS (DELETE FROM app.event WHERE occurred_at<cutoff RETURNING *)
 INSERT INTO app.event_hist SELECT * FROM moved;
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n;
END $$;

-- IMPORTANTE: consolidacion recomputa desde event + event_hist y es idempotente.
CREATE TABLE APP.DAILY_METRIC (
	METRIC_DATE DATE NOT NULL,
	EVENT_TYPE VARCHAR(50) NOT NULL,
	BUSINESS_ID UUID,
	BRANCH_ID UUID,
	TOTAL_COUNT BIGINT NOT NULL CHECK (TOTAL_COUNT >= 0),
	UNIQUE NULLS NOT DISTINCT (METRIC_DATE, EVENT_TYPE, BUSINESS_ID, BRANCH_ID)
);

CREATE INDEX DAILY_METRIC_BRANCH_IDX ON APP.DAILY_METRIC (BRANCH_ID, METRIC_DATE);

CREATE TABLE APP.MONTHLY_METRIC (
	METRIC_MONTH DATE NOT NULL,
	EVENT_TYPE VARCHAR(50) NOT NULL,
	BUSINESS_ID UUID,
	BRANCH_ID UUID,
	TOTAL_COUNT BIGINT NOT NULL CHECK (TOTAL_COUNT >= 0),
	CHECK (
		METRIC_MONTH = DATE_TRUNC('month', METRIC_MONTH)::DATE
	),
	UNIQUE NULLS NOT DISTINCT (METRIC_MONTH, EVENT_TYPE, BUSINESS_ID, BRANCH_ID)
);

CREATE OR REPLACE FUNCTION APP.CONSOLIDATE_DAILY (P_DAY DATE) RETURNS BIGINT LANGUAGE PLPGSQL AS $$
DECLARE n bigint; t0 timestamptz:=p_day::timestamp AT TIME ZONE 'America/La_Paz';
 t1 timestamptz:=(p_day+1)::timestamp AT TIME ZONE 'America/La_Paz';
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('cofre.daily.'||p_day::text));
 DELETE FROM app.daily_metric WHERE metric_date=p_day;
 INSERT INTO app.daily_metric(metric_date,event_type,business_id,branch_id,total_count)
 SELECT p_day,e.event_type,e.business_id,e.branch_id,count(*)
 FROM (SELECT event_type,business_id,branch_id FROM app.event WHERE occurred_at>=t0 AND occurred_at<t1
 UNION ALL SELECT event_type,business_id,branch_id FROM app.event_hist WHERE occurred_at>=t0 AND occurred_at<t1) e
 GROUP BY e.event_type,e.business_id,e.branch_id;
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n;
END $$;

CREATE OR REPLACE FUNCTION APP.CONSOLIDATE_MONTHLY (P_DAY DATE) RETURNS BIGINT LANGUAGE PLPGSQL AS $$
DECLARE m date:=date_trunc('month',p_day)::date; n bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('cofre.monthly.'||m::text));
 DELETE FROM app.monthly_metric WHERE metric_month=m;
 INSERT INTO app.monthly_metric(metric_month,event_type,business_id,branch_id,total_count)
 SELECT m,event_type,business_id,branch_id,sum(total_count) FROM app.daily_metric
 WHERE metric_date>=m AND metric_date<(m+interval '1 month')::date
 GROUP BY event_type,business_id,branch_id;
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n;
END $$;

CREATE OR REPLACE VIEW APP.DASHBOARD_BRANCH_METRICS AS
SELECT
	S.ID AS BRANCH_ID,
	S.BUSINESS_ID,
	COALESCE(
		SUM(DM.TOTAL_COUNT) FILTER (
			WHERE
				DM.EVENT_TYPE = 'branch_view'
		),
		0
	) AS VIEWS,
	COALESCE(
		SUM(DM.TOTAL_COUNT) FILTER (
			WHERE
				DM.EVENT_TYPE = 'contact_click'
		),
		0
	) AS CONTACT_CLICKS,
	COALESCE(
		SUM(DM.TOTAL_COUNT) FILTER (
			WHERE
				DM.EVENT_TYPE = 'directions_click'
		),
		0
	) AS DIRECTIONS_CLICKS,
	COALESCE(
		SUM(DM.TOTAL_COUNT) FILTER (
			WHERE
				DM.EVENT_TYPE = 'ad_impression'
		),
		0
	) AS AD_IMPRESSIONS,
	COALESCE(
		SUM(DM.TOTAL_COUNT) FILTER (
			WHERE
				DM.EVENT_TYPE = 'ad_click'
		),
		0
	) AS AD_CLICKS,
	(
		SELECT
			COUNT(*)
		FROM
			APP.FAVORITE F
		WHERE
			F.BRANCH_ID = S.ID
	) AS FAVORITES,
	(
		SELECT
			ROUND(AVG(R.RATING)::NUMERIC, 2)
		FROM
			APP.REVIEW R
		WHERE
			R.BRANCH_ID = S.ID
			AND R.MODERATION_STATUS = 'visible'
	) AS AVG_RATING
FROM
	APP.BRANCH S
	LEFT JOIN APP.DAILY_METRIC DM ON DM.BRANCH_ID = S.ID
GROUP BY
	S.ID,
	S.BUSINESS_ID;

CREATE OR REPLACE VIEW APP.DASHBOARD_AD_PERFORMANCE AS
SELECT
	A.ID AS AD_ID,
	A.BUSINESS_ID,
	A.BRANCH_ID,
	A.STARTS_AT,
	A.ENDS_AT,
	(
		SELECT
			COUNT(*)
		FROM
			(
				SELECT
					EVENT_TYPE,
					METADATA
				FROM
					APP.EVENT
				UNION ALL
				SELECT
					EVENT_TYPE,
					METADATA
				FROM
					APP.EVENT_HIST
			) X
		WHERE
			X.EVENT_TYPE = 'ad_impression'
			AND X.METADATA ->> 'ad_id' = A.ID::TEXT
	) AS IMPRESSIONS,
	(
		SELECT
			COUNT(*)
		FROM
			(
				SELECT
					EVENT_TYPE,
					METADATA
				FROM
					APP.EVENT
				UNION ALL
				SELECT
					EVENT_TYPE,
					METADATA
				FROM
					APP.EVENT_HIST
			) X
		WHERE
			X.EVENT_TYPE = 'ad_click'
			AND X.METADATA ->> 'ad_id' = A.ID::TEXT
	) AS CLICKS
FROM
	APP.AD_PLACEMENT A
WHERE
	A.ACTIVE;

-- Auditoria de cambios. Se almacena el actor del framework cuando se provee.
CREATE TABLE APP.AUDIT_LOG (
	ID BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
	ENTITY_SCHEMA VARCHAR(63) NOT NULL,
	ENTITY_TABLE VARCHAR(63) NOT NULL,
	OPERATION CHAR(1) NOT NULL CHECK (OPERATION IN ('I', 'U', 'D', 'T')),
	TRANSACTION_ID XID8 NOT NULL DEFAULT PG_CURRENT_XACT_ID(),
	OLD_VALUE JSONB,
	NEW_VALUE JSONB,
	CREATED_BY_USER_ID UUID NOT NULL DEFAULT APP.ACTOR (),
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX AUDIT_ENTITY_IDX ON APP.AUDIT_LOG (ENTITY_SCHEMA, ENTITY_TABLE, CREATED_AT DESC);

CREATE OR REPLACE FUNCTION APP.INSTALL_AUDIT_TRIGGERS (P_TABLE REGCLASS DEFAULT NULL) RETURNS VOID LANGUAGE PLPGSQL AS $$
declare
 r record;
 excluded text[] := array[
  'app.event','app.event_hist','app.daily_metric','app.monthly_metric','app.photo_blob'
 ];
begin
 -- Si app.event se particiona, agregar tambien cada particion a excluded.
 for r in
  select c.oid,c.relispartition,n.nspname,c.relname
  from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
  where c.relkind in ('r','p') and c.relpersistence<>'t'
   and n.nspname not in ('public','information_schema')
   and n.nspname !~ '^pg_' and c.oid<>'app.audit_log'::regclass
   and not ((n.nspname||'.'||c.relname)=any(excluded))
   and (p_table is null or c.oid=p_table)
  order by c.relispartition,c.oid
 loop
  if not r.relispartition or not exists(
   select 1 from pg_catalog.pg_trigger where tgrelid=r.oid and tgname='audit_capture_row'
  ) then
   execute format(
    'CREATE OR REPLACE TRIGGER audit_capture_row AFTER INSERT OR UPDATE OR DELETE ON %I.%I
     FOR EACH ROW EXECUTE FUNCTION app.capture_audit()',r.nspname,r.relname);
  end if;
  if not exists(
   select 1 from pg_catalog.pg_trigger where tgrelid=r.oid and tgname='audit_capture_truncate'
  ) then
   execute format(
    'CREATE TRIGGER audit_capture_truncate BEFORE TRUNCATE ON %I.%I
     FOR EACH STATEMENT EXECUTE FUNCTION app.capture_truncate_audit()',r.nspname,r.relname);
  end if;
 end loop;
end $$;

CREATE OR REPLACE FUNCTION APP.REJECT_PHYSICAL_DELETE () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
begin
 raise exception 'Eliminacion fisica prohibida en %.%; utilice baja logica',tg_table_schema,tg_table_name;
end $$;

CREATE OR REPLACE FUNCTION APP.REJECT_UPDATE () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
begin
 raise exception 'Actualizacion prohibida en %.%; contenido inmutable',tg_table_schema,tg_table_name;
end $$;

CREATE TABLE APP.PHOTO_BLOB (
	SHA256 BYTEA PRIMARY KEY CHECK (OCTET_LENGTH(SHA256) = 32),
	PHOTO_DATA BYTEA NOT NULL CHECK (OCTET_LENGTH(PHOTO_DATA) > 0),
	FILE_SIZE BIGINT GENERATED ALWAYS AS (OCTET_LENGTH(PHOTO_DATA)) STORED,
	CREATED_AT TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	CREATED_BY_USER_ID UUID DEFAULT APP.ACTOR (),
	CHECK (SHA256 = PG_CATALOG.SHA256 (PHOTO_DATA))
);

ALTER TABLE APP.PHOTO_BLOB
ALTER COLUMN PHOTO_DATA
SET
	STORAGE EXTERNAL;

COMMENT ON TABLE APP.PHOTO_BLOB IS 'Archivo inmutable deduplicado por contenido: una imagen de varios negocios comparte fila.
 Los bytes anteriores se archivan al reemplazar, borrar o truncar fotos; las fotos vivas conservan sus bytes.
 Auditoria: solo hash hexadecimal. Sin TOUCH ni auditoria propia.';

CREATE TRIGGER PHOTO_BLOB_NO_UPDATE
BEFORE UPDATE ON APP.PHOTO_BLOB FOR EACH ROW
EXECUTE FUNCTION APP.REJECT_UPDATE ();

CREATE TRIGGER PHOTO_BLOB_NO_DELETE
BEFORE DELETE ON APP.PHOTO_BLOB FOR EACH ROW
EXECUTE FUNCTION APP.REJECT_PHYSICAL_DELETE ();

CREATE TRIGGER PHOTO_BLOB_NO_TRUNCATE
BEFORE TRUNCATE ON APP.PHOTO_BLOB FOR EACH STATEMENT
EXECUTE FUNCTION APP.REJECT_PHYSICAL_DELETE ();

CREATE OR REPLACE FUNCTION APP.CAPTURE_AUDIT () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
declare
 a jsonb;
 b jsonb;
 old_hash bytea;
 new_hash bytea;
 bytes_changed boolean := false;
begin
 if tg_table_schema='app' and tg_table_name in ('branch_photo','business_photo') then
  if tg_op in ('UPDATE','DELETE') then
   old_hash := pg_catalog.sha256(old.photo_data);
   a := (to_jsonb(old)-'photo_data')
    || jsonb_build_object('photo_sha256',encode(old_hash,'hex'));
  end if;
  if tg_op='UPDATE' then
   bytes_changed := new.photo_data is distinct from old.photo_data;
   if bytes_changed then
    new_hash := pg_catalog.sha256(new.photo_data);
   else
    new_hash := old_hash;
   end if;
  elsif tg_op='INSERT' then
   new_hash := pg_catalog.sha256(new.photo_data);
  end if;
  if tg_op in ('INSERT','UPDATE') then
   b := (to_jsonb(new)-'photo_data')
    || jsonb_build_object('photo_sha256',encode(new_hash,'hex'));
  end if;
  if tg_op='DELETE' or bytes_changed then
   -- Trigger AFTER: archivar bytes y auditar es atomico con la modificacion de la foto.
   insert into app.photo_blob(sha256,photo_data) values(old_hash,old.photo_data)
   on conflict (sha256) do nothing;
  end if;
 else
  if tg_op in ('UPDATE','DELETE') then a := to_jsonb(old); end if;
  if tg_op in ('INSERT','UPDATE') then b := to_jsonb(new); end if;
 end if;
 insert into app.audit_log(entity_schema,entity_table,operation,created_by_user_id,old_value,new_value)
 values(tg_table_schema,tg_table_name,left(tg_op,1),app.actor(),a,b);
 return null;
end $$;

CREATE OR REPLACE FUNCTION APP.CAPTURE_TRUNCATE_AUDIT () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
begin
 if tg_table_schema='app' and tg_table_name in ('branch_photo','business_photo') then
  -- BEFORE TRUNCATE conserva todos los bytes antes del snapshot; todo en la misma transaccion.
  execute format(
   'INSERT INTO app.photo_blob(sha256,photo_data)
    SELECT pg_catalog.sha256(r.photo_data),r.photo_data FROM %I.%I r
    ON CONFLICT (sha256) DO NOTHING',tg_table_schema,tg_table_name);
  execute format(
   'INSERT INTO app.audit_log(entity_schema,entity_table,operation,created_by_user_id,old_value)
    SELECT $1,$2,''T'',app.actor(),
     (to_jsonb(r)-''photo_data'')
      || jsonb_build_object(''photo_sha256'',encode(pg_catalog.sha256(r.photo_data),''hex''))
    FROM %I.%I r',tg_table_schema,tg_table_name)
  using tg_table_schema,tg_table_name;
 else
  execute format(
   'INSERT INTO app.audit_log(entity_schema,entity_table,operation,created_by_user_id,old_value)
    SELECT $1,$2,''T'',app.actor(),to_jsonb(r) FROM %I.%I r',tg_table_schema,tg_table_name)
  using tg_table_schema,tg_table_name;
 end if;
 return null;
end $$;

CREATE OR REPLACE FUNCTION APP.RECOVER_PHOTO (P_SHA256 BYTEA) RETURNS BYTEA LANGUAGE SQL STABLE AS $$
 select coalesce(
  (select b.photo_data from app.photo_blob b where b.sha256=p_sha256),
  (select p.photo_data from app.branch_photo p where p.photo_sha256=p_sha256 limit 1),
  (select p.photo_data from app.business_photo p where p.photo_sha256=p_sha256 limit 1)
 )
$$;

CREATE OR REPLACE VIEW APP.AUDIT_PHOTO_HISTORY AS
SELECT
	ENTITY_TABLE,
	OPERATION,
	CREATED_AT,
	CREATED_BY_USER_ID,
	OLD_VALUE ->> 'id' AS OLD_PHOTO_ID,
	OLD_VALUE ->> 'photo_sha256' AS OLD_PHOTO_SHA256,
	NEW_VALUE ->> 'photo_sha256' AS NEW_PHOTO_SHA256
FROM
	APP.AUDIT_LOG
WHERE
	ENTITY_SCHEMA = 'app'
	AND ENTITY_TABLE IN ('branch_photo', 'business_photo');

CREATE OR REPLACE FUNCTION APP.PROTECT_AUDIT_LOG () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
BEGIN
 -- El log es el destino de la auditoria, no se audita recursivamente.
 -- Solo los triggers de captura insertan; UPDATE, DELETE y TRUNCATE siempre se rechazan.
 IF TG_OP='INSERT' AND pg_trigger_depth()>1 THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'El registro de auditoria es inmutable y solo admite inserciones de captura';
END $$;

CREATE TRIGGER AUDIT_LOG_IMMUTABLE
BEFORE INSERT OR UPDATE OR DELETE ON APP.AUDIT_LOG FOR EACH ROW
EXECUTE FUNCTION APP.PROTECT_AUDIT_LOG ();

CREATE TRIGGER AUDIT_LOG_NO_TRUNCATE
BEFORE TRUNCATE ON APP.AUDIT_LOG FOR EACH STATEMENT
EXECUTE FUNCTION APP.PROTECT_AUDIT_LOG ();

-- Politica comun: no incluir objetos de extensiones alojados en public.
CREATE OR REPLACE FUNCTION APP.INSTALL_TABLE_POLICIES (P_TABLE REGCLASS DEFAULT NULL) RETURNS VOID LANGUAGE PLPGSQL AS $$
DECLARE r record; state_column text; deleted_state text;
BEGIN
 FOR r IN SELECT c.oid,n.nspname,c.relname FROM pg_class c
 JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.relkind IN ('r','p') AND c.relpersistence<>'t'
  AND n.nspname<>'information_schema' AND n.nspname !~ '^pg_'
  AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass
   AND d.objid=c.oid AND d.deptype='e' AND d.refclassid='pg_extension'::regclass)
  AND (p_table IS NULL OR c.oid=p_table)
 LOOP
  -- Lista cerrada para eventos/fotos; sufijo exacto para metricas.
  IF NOT (r.nspname='app' AND (r.relname IN
   ('event','event_hist','branch_photo','business_photo','favorite') OR right(r.relname,7)='_metric'))
  THEN
   IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=r.oid
    AND tgfoid='app.reject_physical_delete()'::regprocedure AND (tgtype::int & 8)=8) THEN
    EXECUTE format('CREATE TRIGGER policy_no_delete BEFORE DELETE ON %I.%I
     FOR EACH ROW EXECUTE FUNCTION app.reject_physical_delete()',r.nspname,r.relname);
   END IF;
   IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=r.oid
    AND tgfoid IN ('app.reject_physical_delete()'::regprocedure,'app.protect_audit_log()'::regprocedure)
    AND (tgtype::int & 32)=32) THEN
    EXECUTE format('CREATE TRIGGER policy_no_truncate BEFORE TRUNCATE ON %I.%I
     FOR EACH STATEMENT EXECUTE FUNCTION app.reject_physical_delete()',r.nspname,r.relname);
   END IF;
  END IF;
  -- La proteccion de borrado es independiente: public nunca recibe TOUCH.
  IF r.nspname<>'public' AND (SELECT count(*)=6 FROM pg_attribute WHERE attrelid=r.oid AND NOT attisdropped
   AND attname IN ('created_at','created_by_user_id','updated_at','updated_by_user_id','deleted_at','deleted_by_user_id'))
   AND NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=r.oid AND tgfoid='app.touch()'::regprocedure)
  THEN
   state_column:=NULL; deleted_state:=NULL;
   IF r.nspname='app' THEN
    SELECT v.col,v.code INTO state_column,deleted_state FROM (VALUES
     ('business','status','archived'),('branch','status','permanently_closed'),
     ('review','moderation_status','deleted'),('business_subscription','status','cancelled'),
     ('subscription_payment','status','cancelled')) v(tbl,col,code) WHERE v.tbl=r.relname;
   END IF;
   -- Nuevas tablas con estados deben registrar aqui su codigo de baja.
   EXECUTE format('CREATE TRIGGER metadata_touch BEFORE INSERT OR UPDATE ON %I.%I
    FOR EACH ROW EXECUTE FUNCTION app.touch(%s)',r.nspname,r.relname,
    CASE WHEN state_column IS NULL THEN '' ELSE format('%L,%L',state_column,deleted_state) END);
  END IF;
 END LOOP;
END $$;

SELECT
	APP.INSTALL_TABLE_POLICIES ();

SELECT
	APP.INSTALL_AUDIT_TRIGGERS ();

-- Las tablas nuevas de las migraciones EF reciben cobertura automaticamente.
-- Crear el event trigger requiere el usuario de inicializacion con privilegio de superusuario.
CREATE OR REPLACE FUNCTION APP.AUDIT_NEW_TABLES () RETURNS EVENT_TRIGGER LANGUAGE PLPGSQL AS $$
DECLARE cmd record;
BEGIN
 FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands() LOOP
  IF cmd.classid='pg_class'::regclass AND cmd.objsubid=0 THEN
   PERFORM app.install_audit_triggers(cmd.objid::regclass);
   PERFORM app.install_table_policies(cmd.objid::regclass);
  END IF;
 END LOOP;
END $$;

CREATE EVENT TRIGGER AUDIT_TABLE_COVERAGE ON DDL_COMMAND_END WHEN TAG IN (
	'CREATE TABLE',
	'CREATE TABLE AS',
	'SELECT INTO',
	'ALTER TABLE'
)
EXECUTE FUNCTION APP.AUDIT_NEW_TABLES ();

-- La validacion se difiere para permitir crear negocio, sucursal y categorias en una transaccion.
-- Un negocio puede publicarse y permanecer sin sucursales. Si tiene sucursales
-- vigentes, cada una debe tener categoria; BUSINESS_ID siempre es NOT NULL con FK.
CREATE OR REPLACE FUNCTION APP.CHECK_PUBLICATION_CATEGORIES () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
DECLARE bid uuid;
BEGIN
 IF TG_TABLE_NAME='business' THEN
  bid:=NEW.id;
 ELSE
  bid:=NEW.business_id;
 END IF;
 IF EXISTS(SELECT 1 FROM app.business WHERE id=bid AND status='published')
 THEN
  IF EXISTS(SELECT 1 FROM app.branch s WHERE s.business_id=bid AND s.status IN ('active','temporarily_closed')
   AND NOT EXISTS(SELECT 1 FROM app.branch_category bc JOIN catalog.category c ON c.id=bc.category_id AND c.active
    WHERE bc.branch_id=s.id AND bc.active))
  THEN RAISE EXCEPTION 'Cada sucursal publicada requiere categoria vigente'; END IF;
 END IF;
 RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER BUSINESS_PUBLICATION_CATEGORY
AFTER INSERT OR UPDATE OF STATUS ON APP.BUSINESS
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION APP.CHECK_PUBLICATION_CATEGORIES ();

CREATE CONSTRAINT TRIGGER BRANCH_PUBLICATION_CATEGORY
AFTER INSERT OR UPDATE OF BUSINESS_ID,
STATUS ON APP.BRANCH
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION APP.CHECK_PUBLICATION_CATEGORIES ();

-- Las bajas de categorias/asociaciones tambien deben mantener la publicacion.
CREATE OR REPLACE FUNCTION APP.CHECK_CATEGORY_COVERAGE () RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
DECLARE new_row jsonb:=to_jsonb(NEW); old_row jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN old_row:=to_jsonb(OLD); END IF;
 IF EXISTS(SELECT 1 FROM app.branch s JOIN app.business b ON b.id=s.business_id
  WHERE ((TG_TABLE_NAME='branch_category' AND s.id IN
    ((new_row->>'branch_id')::uuid,(old_row->>'branch_id')::uuid)) OR
   (TG_TABLE_NAME='category' AND EXISTS(SELECT 1 FROM app.branch_category changed
    WHERE changed.branch_id=s.id AND changed.category_id IN
     ((new_row->>'id')::uuid,(old_row->>'id')::uuid))))
   AND b.status='published' AND s.status IN ('active','temporarily_closed')
   AND NOT EXISTS(SELECT 1 FROM app.branch_category bc JOIN catalog.category c ON c.id=bc.category_id
    WHERE bc.branch_id=s.id AND bc.active AND c.active))
 THEN RAISE EXCEPTION 'Cada sucursal publicada requiere categoria vigente'; END IF;
 RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER ASSIGNMENT_CATEGORY_COVERAGE
AFTER INSERT OR UPDATE ON APP.BRANCH_CATEGORY
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION APP.CHECK_CATEGORY_COVERAGE ();

CREATE CONSTRAINT TRIGGER CATALOG_CATEGORY_COVERAGE
AFTER UPDATE OF ACTIVE ON CATALOG.CATEGORY
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION APP.CHECK_CATEGORY_COVERAGE ();

-- Operaciones del dashboard (la identidad de administrador se valida en el backend).
CREATE OR REPLACE FUNCTION APP.ADMIN_UPDATE_BUSINESS (
	P_BUSINESS_ID UUID,
	P_ACTOR UUID,
	P_NAME TEXT,
	P_DESCRIPTION TEXT
) RETURNS VOID LANGUAGE PLPGSQL AS $$
BEGIN
 UPDATE app.business SET trade_name=p_name,description=p_description,
 updated_by_user_id=p_actor WHERE id=p_business_id AND status <> 'archived';
 IF NOT FOUND THEN RAISE EXCEPTION 'Negocio inexistente o inactivo'; END IF;
END $$;

CREATE OR REPLACE FUNCTION APP.ADMIN_PUBLISH_BUSINESS (P_BUSINESS_ID UUID, P_ACTOR UUID) RETURNS VOID LANGUAGE PLPGSQL AS $$
BEGIN
 UPDATE app.business SET status='published',updated_by_user_id=p_actor
 WHERE id=p_business_id AND status <> 'archived';
 IF NOT FOUND THEN RAISE EXCEPTION 'Negocio no encontrado'; END IF;
END $$;

CREATE OR REPLACE FUNCTION APP.MODERATE_REVIEW (
	P_REVIEW_ID UUID,
	P_STATUS TEXT,
	P_REASON TEXT,
	P_ACTOR UUID
) RETURNS VOID LANGUAGE PLPGSQL AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM catalog.review_moderation_status WHERE code=p_status AND active) THEN RAISE EXCEPTION 'Estado invalido'; END IF;
 UPDATE app.review SET moderation_status=p_status,moderation_reason=p_reason,
 moderated_by_user_id=p_actor,moderated_at=now()
 WHERE id=p_review_id AND moderation_status <> 'deleted';
 IF NOT FOUND THEN RAISE EXCEPTION 'Resena no encontrada'; END IF;
END $$;

CREATE OR REPLACE FUNCTION APP.SET_PRIMARY_PHOTO (
	P_BRANCH_ID UUID,
	P_PHOTO_ID UUID,
	P_ACTOR UUID,
	P_IS_ADMIN BOOLEAN DEFAULT FALSE
) RETURNS VOID LANGUAGE PLPGSQL AS $$
DECLARE bid uuid;
BEGIN
 SELECT business_id INTO STRICT bid FROM app.branch WHERE id=p_branch_id AND status IN ('active','temporarily_closed');
 IF NOT coalesce(p_is_admin,false) AND NOT app.is_business_owner(p_actor,bid) THEN RAISE EXCEPTION 'Permiso denegado'; END IF;
 IF NOT EXISTS(SELECT 1 FROM app.branch_photo WHERE id=p_photo_id AND branch_id=p_branch_id AND active) THEN
  RAISE EXCEPTION 'Foto inexistente'; END IF;
 UPDATE app.branch_photo SET is_primary=true WHERE id=p_photo_id;
END $$;

CREATE OR REPLACE VIEW APP.ADMIN_BUSINESS_SUMMARY AS
SELECT
	B.ID,
	B.TRADE_NAME,
	B.STATUS,
	B.DELETED_AT,
	(
		SELECT
			COUNT(*)
		FROM
			APP.BRANCH S
		WHERE
			S.BUSINESS_ID = B.ID
			AND S.STATUS IN ('active', 'temporarily_closed')
	) AS ACTIVE_BRANCHES,
	(
		SELECT
			COUNT(*)
		FROM
			APP.BUSINESS_OWNER O
		WHERE
			O.BUSINESS_ID = B.ID
			AND O.ACTIVE
	) AS OWNERS,
	(
		SELECT
			COUNT(*)
		FROM
			APP.REVIEW R
			JOIN APP.BRANCH S ON S.ID = R.BRANCH_ID
		WHERE
			S.BUSINESS_ID = B.ID
			AND R.MODERATION_STATUS <> 'deleted'
	) AS REVIEWS,
	(
		SELECT
			COUNT(*)
		FROM
			APP.AD_PLACEMENT A
		WHERE
			A.ACTIVE
			AND (
				A.BUSINESS_ID = B.ID
				OR A.BRANCH_ID IN (
					SELECT
						ID
					FROM
						APP.BRANCH
					WHERE
						BUSINESS_ID = B.ID
				)
			)
	) AS ADS
FROM
	APP.BUSINESS B;

-- DELETE/TRUNCATE se protegen con install_table_policies tambien en tablas nuevas.
-- Solo event/event_hist, branch_photo/business_photo, favorite y *_metric admiten borrado fisico.
-- photo_blob y audit_log mantienen su contrato inmutable.
-- Datos de configuracion indispensables.
INSERT INTO
	CATALOG.PARAMETER_DEFINITION (
		CODE,
		DESCRIPTION,
		DATA_TYPE,
		DEFAULT_VALUE,
		MIN_NUMBER,
		MAX_NUMBER
	)
VALUES
